function createEnv(sdk) {
  var MAX_STEPS = 1800;
  var rng;
  var ballX, ballY, ballVX, ballVY, paddleX;
  var t, done, catchCount;
  var terms = [0, 0, 0, 0, 0];
  var obs = [0, 0, 0, 0, 0, 0, 0];

  function difficulty() {
    return sdk.clamp(t / 1050 + catchCount / 42, 0, 1);
  }

  function gravity() {
    return 0.18 + 0.13 * difficulty();
  }

  function halfWidth() {
    return 64 - 28 * difficulty();
  }

  function landingX() {
    var g = gravity();
    var dy = 432 - ballY;
    var disc = ballVY * ballVY + 2 * g * dy;
    var flight = (-ballVY + Math.sqrt(Math.max(0, disc))) / g;
    flight = sdk.clamp(flight, 0, 200);

    var span = 730;
    var period = span * 2;
    var q = ballX - 35 + ballVX * flight;
    q = ((q % period) + period) % period;
    if (q > span) q = period - q;
    return 35 + q;
  }

  return {
    reset: function (seed) {
      rng = sdk.rng(seed);
      ballX = rng.range(330, 470);
      ballY = 190;
      ballVX = rng.range(-2.4, 2.4);
      ballVY = 1.5;
      paddleX = 400;
      t = 0;
      done = false;
      catchCount = 0;
      for (var i = 0; i < terms.length; i++) terms[i] = 0;
    },

    step: function (action) {
      if (done) return;

      var dir = action === 0 ? -1 : (action === 2 ? 1 : 0);
      var d = difficulty();
      var oldY = ballY;
      var g = gravity();
      var hw = halfWidth();

      paddleX = sdk.clamp(paddleX + dir * (8.5 - 1.5 * d), 80, 720);
      if (dir !== 0) terms[4] += 1 / MAX_STEPS;

      ballX += ballVX;
      if (ballX < 35) {
        ballX = 70 - ballX;
        ballVX = Math.abs(ballVX);
      } else if (ballX > 765) {
        ballX = 1530 - ballX;
        ballVX = -Math.abs(ballVX);
      }

      ballY += ballVY;
      ballVY += g;

      if (ballY < 35) {
        ballY = 35;
        ballVY = Math.abs(ballVY) * 0.98;
      }

      if (ballVY > 0 && oldY < 432 && ballY >= 432) {
        if (Math.abs(ballX - paddleX) <= hw + 10) {
          var offset = sdk.clamp((ballX - paddleX) / hw, -1, 1);
          ballY = 431;
          ballVX = sdk.clamp(ballVX * 0.88 + offset * (2 + 2.2 * d), -6.5, 6.5);
          ballVY = -(11.8 + 1.8 * d);
          catchCount += 1;
          terms[0] += 1;
        } else {
          terms[3] += 1;
          done = true;
        }
      }

      t += 1;
      terms[1] += 1 / MAX_STEPS;

      if (!done && ballVY > 0) {
        var distance = Math.abs(landingX() - paddleX);
        terms[2] += Math.max(0, 1 - distance / 400) / MAX_STEPS;
      }

      if (t >= MAX_STEPS) done = true;
    },

    observe: function () {
      obs[0] = (ballX - 400) / 365;
      obs[1] = (ballY - 250) / 250;
      obs[2] = ballVX / 7;
      obs[3] = ballVY / 14;
      obs[4] = (paddleX - 400) / 320;
      obs[5] = (halfWidth() - 50) / 20;
      obs[6] = difficulty();
      return obs;
    },

    get done() {
      return done;
    },

    terms: terms,

    render: function (draw, ghost) {
      if (!ghost) {
        draw.clear(sdk.colors.bg);
        draw.line(35, 35, 765, 35, sdk.colors.dim, 2);
        draw.line(35, 432, 765, 432, sdk.colors.dim, 2);
        draw.text("Catches: " + catchCount, 24, 32, sdk.colors.fg, 18);
        draw.text("Difficulty: " + Math.round(difficulty() * 100) + "%", 650, 32, sdk.colors.dim, 15);
        draw.circle(ballX, ballY, 10, sdk.colors.warn);
      }
      draw.rect(paddleX - halfWidth(), 432, halfWidth() * 2, 14, sdk.colors.accent);
    },

    humanAct: function (input) {
      if (input.held.has("ArrowLeft")) return 0;
      if (input.held.has("ArrowRight")) return 2;
      return 1;
    }
  };
}
